// spec: .qa/e2e/specs/reminders.md
// seed: tests/seed.user1.spec.ts
// Только чтение: даты — подменой часов браузера; местоположение user1 (פתח תקווה) не меняется.
// Сценарий фикса c695450 (генератор удаляет строки других дней): вперёд-назад по датам — строка возвращается и не дублируется.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { openHomeAt, tefillinRows, duplicateTitles, restoreTodayReminders } from '../_helpers/reminders';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  timezoneId: 'Asia/Jerusalem',
});

const SEQ: { day: string; note: string }[] = [
  { day: '2026-10-05', note: 'первый показ' },
  { day: '2026-10-15', note: 'вперёд на 10 дней' },
  { day: '2026-10-05', note: 'назад — строка снова есть' },
  { day: '2026-10-06', note: 'на день вперёд' },
  { day: '2026-10-05', note: 'на день назад — одна строка, не две' },
  { day: '2026-10-04', note: 'אסרו חג (Израиль) после более поздних дней' },
];

test.describe('Напоминания', () => {
  test('RM-07 Даты вперёд-назад (5.10→15.10→5.10→6.10→5.10→4.10) — «הנחת תפילין» ровно одна, без дублей «ראש חודש» #3cc72778 @prod-safe @mobile', async ({ page, browser }, testInfo) => {
    try {
      for (const [i, s] of SEQ.entries()) {
        await test.step(`${i + 1}. ${s.day} 12:00 — ${s.note}`, async () => {
          const rows = await openHomeAt(page, `${s.day}T12:00:00+03:00`, { expectDay: s.day });
          // источник: «מה רצוי» — строка в каждый день, когда надевают תפילין; комментарий программиста 4.10 14:11 — ровно одна
          expect(tefillinRows(rows), `строк «הנחת תפילין» на ${s.day}`).toHaveLength(1);
          expect(duplicateTitles(rows), 'дубли «הנחת תפילין» / «ראש חודש»').toEqual([]);
        });
      }
    } finally {
      await restoreTodayReminders(browser, testInfo);
    }
  });
});
